use projects;
 create table Reserves (
    reserve_id in T PRIMARY KEY,
    reserve_name VARCHAR(80) not  NULL UNIQUE,
    country VARCHAR(50) not  NULL,
    area_sq_km in T CHECK (area_sq_km > 0),
    established_year in T CHECK (established_year >= 1900)
);

