 create table Animals (
    animal_id in T PRIMARY KEY,
    tag_code VARCHAR(20) not  NULL UNIQUE,
    species_id in T,
    reserve_id in T,
    sex VARCHAR(10) CHECK (sex in  ('Male', 'Female', 'Unknown')),
    estimated_age in T CHECK (estimated_age >= 0),
    collar_fitted_date DATE not  NULL,
    FOREIGN KEY (species_id) REFERENCES Species(species_id),
    FOREIGN KEY (reserve_id) REFERENCES Reserves(reserve_id)
);

