select*  from Reserves;
select*  from Species ;
select*  from Animals ;
select*  from GPSLogs ;



/*====================================================
	                  c aseS
=====================================================*/
-- 1. A researcher's fieldwork contract h as just ended, and their access to  the datab ase needs to  be fully withdrawn with immediate effect.

 create user 'researcher_username'@'localhost' identified by 'research@123';

grant all privileges on Projects.* to  'researcher_username'@'localhost';

show grants for 'researcher_username'@'localhost';

revoke update   on  Projects.*  from  'researcher_username'@'localhost';


-- 2. Group all GPS pin gs by the animal they belong to , and flag animals with fewer than 5 to tal pin gs recorded so far — their collars might be malfunctionin g.

select animal_id, COUNT(*)  as total_pings
 from GPSLogs
group by animal_id
having COUNT(*) < 5
order by   total_pings;

-- 3. Some reserves may not  have a sin gle animal collared yet. Identify exactly which ones, sin ce this is a cover age gap worth flaggin g to  the programme directo r.

select r.reserve_id, r.reserve_name
 from Reserves r
left join  Animals a
on r.reserve_id = a.reserve_id
where a.animal_id is null;

-- 4. The steerin g committee wants to  know, in  one number, how many distin ct  species are currently bein g monito red across all reserves combin ed.

select count(distinct  species_id)  as species_monitored
 from Animals;

-- 5. An in tern wants to  flag any reserve name that's unusually long (more than 25 characters) so it can be shortened for the mobile app's limited screen space.
select reserve_id, reserve_name, length(reserve_name)  as name_length
 from Reserves
where length(reserve_name) > 25;

-- 6. Sort each animal's estimated age in to  'Juvenile', 'Adult', or 'Senior' bands usin g sensible thresholds, to  help the biology team study age distribution across the population.
select animal_id, tag_code, estimated_age,
case
when estimated_age < 5 then 'Juvenile'
when estimated_age < 15 then 'Adult'
else'Senior'
end  as age_band
 from Animals;

-- 7. For each reserve, smooth out momentary sensor glitches by calculatin g an average battery level usin g only the current readin g and the two immediately before it.

select g.log_id, a.reserve_id, g.log_datetime, g.battery_level_pct,
AVG(g.battery_level_pct) over (
partition by reserve_id
order by   g.log_datetime
rows between 2 preceding and current row
)  as smoothed_avg_battery
 from GPSLogs g
inner join  Animals a
on g.animal_id = a.animal_id
order by   a.reserve_id, g.log_datetime;

-- 8. Break this in to  two steps: first fin d each animal's most recent log date, then use that to  identify which animals haven't reported anythin g in  the l ast 10 days.

with last_seen  as (
select animal_id, MAX(log_datetime)  as last_log
 from GPSLogs
group by animal_id
)
select a.animal_id, a.tag_code, ls.l ast_log
 from Animals a
inner join  l ast_seenls 
on a.animal_id = ls.animal_id
where ls.last_log < current_date - interval 10 day;

-- 9. Some tag codes were typed with in consistent capitalization by different rangers over  the years. Produce a clean, uniformly capitalized list for the trackin g d ashboard.

select animal_id, UPPER(tag_code)  as tag_code_clean
 from Animals
order  by   tag_code_clean;

-- 10. First tally each species' to tal tracked population, then brin g in  reserve details to  see which reserves are hostin g the heaviest concentrations of the most vulnerable species.

with species_totals  as (
select species_id, count(*)  as population
 from Animals
group by species_id
)
select r.reserve_name, s.species_name, s.conservation_status,
count(a.animal_id)  as individuals_in_reserve,
st.population  as species_total_population
 from  Animals a
inner join  Reserves r
on a.reserve_id = r.reserve_id
inner join  Species s 
on a.species_id = s.species_id
inner join  species_to talsst 
on  s.species_id = st.species_id
where s.conservation_status in ('Endangered', 'Critically Endangered')
group by r.reserve_name, s.species_name, s.conservation_status, st.population
order by   individuals_in_reserve desc ;

-- 11. Identify every animal whose collar w as fitted more than two years ago — these units are approachin g the end of their expected workin g life and should be flagged for replacement.

select animal_id, tag_code, collar_fitted_date
 from Animals
where collar_fitted_date < CURRENT_DATE - interval 2 year ;

-- 12. Fin d the lowest battery level ever recorded across all collars — that particular device may need an urgent field swap.

select log_id, animal_id, battery_level_pct
 from GPSLogs
order by    battery_level_pct  asc
limit 1;

-- 13. A ranger wants to  know which day of the week sees the most recorded animal movement, purely to  plan patrol shifts more efficiently.

select DAYNAME(log_datetime)  as day_of_week, COUNT(*)  as log_count
 from GPSLogs
group by DAYNAME(log_datetime)
order by   log_count desc 
limit 1;

-- 14. The d ashboard team wants somethin g they can plug straight in to  their reportin g to ol that always reflects each reserve's current animal count and average battery health, without re-derivin g it manually
-- each time.

 create view ReserveDashboard  as
select r.reserve_id, r.reserve_name,
COUNT(distinct  a.animal_id)  as animal_count,
AVG(g.battery_level_pct)     as avg_battery_health
 from Reserves r
LEFT JOin  Animals a
on r.reserve_id = a.reserve_id
LEFT JOin  GPSLogs g
on a.animal_id  = g.animal_id
group by r.reserve_id, r.reserve_name;
 
-- 15. Pull every GPS log recorded durin g the month of June this year, to  study how the tracked animals behaved durin g the onset  of monsoon rain s.

select *
 from GPSLogs
where EXTRACT(YEAR  from log_datetime)  = EXTRACT(YEAR  from CURRENT_DATE)
and EXTRACT(MonTH  from log_datetime) = 6;

-- 16. For each species, build a runnin g count of how many animals have been collared over  time, ordered by fittin g date, to  visualize how the programme h as grown.

select species_id, animal_id, collar_fitted_date,
ROW_NUMBER() over  (PARTITIon BY species_id order by   collar_fitted_date)  as running_count
 from Animals
order by   species_id, collar_fitted_date;

-- 17. Prepare a field report listin g every animal along with its species name and the reserve it currently roams in , all on a sin gle lin e per animal.

select a.tag_code, s.species_name, r.reserve_name
 from Animals a
inner join  Species s 
on a.species_id  = s.species_id
inner join  Reserves r
on a.reserve_id  = r.reserve_id;
-- 18. The system currently lets someone log a battery level of 150% by mistake. What change would permanently make this impossible goin g forward?

alter  table GPSLogs
add  constraint  chk_battery_range CHECK (battery_level_pct between 0 and 100);

-- 19. For a specific animal that's causin g concern, work out how many hours have p assed between its very first logged position and its most recent one, 
-- to  check whether the collar is still reportin g normally.

select animal_id,
TIMESTAMPDIFF(HOUR, Min (log_datetime), MAX(log_datetime))  as hours_span
 from GPSLogs
where animal_id = 101
group by animal_id;

-- 20. For each animal, work out how many days have p assed sin ce its collar w as first fitted — this determin es which ones are due for the routin e 180-day battery check.

select animal_id, tag_code, collar_fitted_date,
DATEDIFF(CURDATE(), collar_fitted_date)  as days_since_fitted
 from Animals
where DATEDIFF(CURDATE(), collar_fitted_date) >= 180;

-- 21. Flag each reserve  as 'over crowded', 'Balanced', or 'Under-monito red' b ased on how many animals are currently tracked there relative to  the reserve's area.

select r.reserve_id, r.reserve_name, r.area_sq_km,
COUNT(a.animal_id)  as animal_count,
ROUND(COUNT(a.animal_id) * 1000.0 / r.area_sq_km, 2)  as animals_per_1000_sqkm,
case
when COUNT(a.animal_id) * 1000.0 / r.area_sq_km > 10 then 'over crowded'
when COUNT(a.animal_id) * 1000.0 / r.area_sq_km < 3  then 'Under-monito red'
else 'Balanced'
end  as density_flag
 from Reserves r
LEFT JOin  Animals a 
on r.reserve_id = a.reserve_id
group by r.reserve_id, r.reserve_name, r.area_sq_km;

-- 22. For the upcomin g fundin g proposal, work out the average estimated age of every Critically Endangered animal currently in  the system.

select AVG(a.estimated_age)  as avg_age_critically_endangered
 from Animals a
inner join  Species s on a.species_id = s.species_id
where s.conservation_status = 'Critically Endangered';

-- 23. Label each collar's current battery level  as 'Critical' (below 15%), 'Low' (15–40%), or 'Healthy' (above 40%), so field teams in stantly know which ones need urgent attention.

select log_id, animal_id, battery_level_pct,
case
when battery_level_pct < 15 then 'Critical'
when battery_level_pct between 15 and 40   then 'Low'
else 'Healthy'
end  as battery_status
 from GPSLogs;

-- 24. Identify which reserves have recorded an average animal speed above 15 km/h over  the l ast month, which could poin t to  unusual stress or fleein g behaviour spreadin g across the local population.

select r.reserve_id, r.reserve_name, AVG(g.speed_kmph)  as avg_speed
 from Reserves r
inner join  Animals a 
on r.reserve_id = a.reserve_id
inner join  GPSLogs g 
on a.animal_id  = g.animal_id
where g.log_datetime >= DATE_SUB(CURDATE(), interval 1 MonTH)
group by r.reserve_id, r.reserve_name
having AVG(g.speed_kmph) > 15;

-- 25. For each species, count the number of in dividuals currently bein g tracked, and highlight any species where fewer than 10 in dividuals are monito red — a conservation priority signal.

select s.species_id, s.species_name, COUNT(a.animal_id)  as individual_count,
case when COUNT(a.animal_id) < 10 then 'Conservation Priority' else '' end  as priority_flag
 from Species s
LEFT JOin  Animals a on s.species_id = a.species_id
group by s.species_id, s.species_name;

-- 26. For each animal, flag any of its own GPS logs where the recorded speed is not iceably higher than that same animal's own typical speed — a possible burst of unusual activity worth a closer look.

select *
 from (select g.*, AVG(g.speed_kmph) over  (PARTITIon BY g.animal_id)  as animal_avg_speed
 from GPSLogs g
) t
where speed_kmph > animal_avg_speed * 1.5
order by   animal_id, log_datetime;

-- 27. Track down which reserve is home to  the animal that recorded the sin gle highest speed anywhere in  the entire dat aset .

select r.reserve_name, a.animal_id, g.speed_kmph
 from GPSLogs g
inner join  Animals a 
on g.animal_id  = a.animal_id
inner join  Reserves r
on a.reserve_id = r.reserve_id
order by   g.speed_kmph desc 
limit 1;

-- 28. Rangers constantly search GPS logs usin g a specific animal's ID to  pull up its full movement histo ry in stantly, but this lookup h as started to  feel sluggish now that the log table h as grown in to  the
-- thousands. What would you do about it?

 create index idx_gpslogs_animal_id on GPSLogs(animal_id);

-- 29. An animal previously  assumed dead h as just been confirmed alive and re-collared in  the field. Reflect this by recordin g its new collar-fittin g date.

update   Animals
set  collar_fitted_date = '2026-07-29'
where animal_id = 151; 
  
-- 30. For a lamin ated field handout, combin e each animal's tag code and species name in to  a sin gle readable label, separated by a d ash.

select a.tag_code || '-' || s.species_name  as field_label
 from Animals a
inner join  Species s
on a.species_id = s.species_id;

-- 31. Work out how many animals have been fitted with collars in  each in dividual reserve, to  see where the trackin g effort is concentrated.

select reserve_id, COUNT(*)  as animal_count
 from Animals
group by reserve_id
order by   animal_count desc ;

-- 32. Work this out in  two stages: first tally up each animal's to tal number of logs this month, then use that to  shortlist animals logged fewer than 3 times — these may have gone quiet.

WITH monthly_counts  as (
select animal_id, COUNT(*)  as log_count
 from GPSLogs
where EXTRACT(YEAR  from log_datetime)  = EXTRACT(YEAR  from CURRENT_DATE)
and EXTRACT(MonTH  from log_datetime) = EXTRACT(MonTH  from CURRENT_DATE)
group by animal_id
)
select animal_id, log_count
 from monthly_counts
where log_count < 3;

-- 33. Estimate how many field battery-replacement trips are needed this month by fin din g the average 

select AVG(battery_level_pct)  as avg_battery_all_readings
 from GPSLogs;

-- 34. For every species bein g tracked, list out all the reserves where at le ast one in dividual of that species currently carries a collar.

select distinct  s.species_name, r.reserve_name
 from Animals a
inner join  Species s
on a.species_id  = s.species_id
inner join  Reserves r
on a.reserve_id  = r.reserve_id
order by   s.species_name, r.reserve_name;

-- 35. List all animals currently b ased in  one of the three largest reserves by area.

select a.*
 from Animals a
where a.reserve_id in  (
select reserve_id  from (
select reserve_id  from Reserves order by   area_sq_km desc  limit 3
)  as top3
);

-- 36. Identify any animal that h as never had a sin gle GPS pin g recorded again st it — this is a critical operational failure that needs immediate attention.

select a.*
 from Animals a
inner join  (select reserve_id  from Reserves 
order by   area_sq_km desc  limit 3
)  as top3
on a.reserve_id = top3.reserve_id;

-- 37. The programme directo r wants a sin gle number for the board meetin g: exactly how many animals are currently bein g tracked across the entire alliance.

select COUNT(*)  as total_tracked_animals
 from Animals;

-- 38. Goin g forward, the programme wants to  record which manufacturer supplied each animal's GPS collar. Adjust the animal records so this detail can be captured.

alter  table Animals
add  COLUMN collar_manufacturer VARCHAR(50);

-- 39. Two rangers in  different reserves accidentally try to  register the same tag code for two different animals on the same day. What should sto p this  from happenin g?

--
alter  table Animals DROP index uq_tag_code;
alter  table Animals add  constraint uq_tag_code UNIQUE (tag_code);

-- 40. For every reserve, surface the sin gle f astest animal recorded there without losin g any of the reserve's other animal rows in  the process — every animal should still show up in  the result.

select a.reserve_id, a.animal_id, g.speed_kmph,
MAX(g.speed_kmph) over  (PARTITIon BY a.reserve_id)  as fastest_in_reserve
 from Animals a
inner join  GPSLogs g
on a.animal_id = g.animal_id;

-- 41. Fin d the sin gle highest speed ever recorded by any collar so far — this readin g could poin t to  a ch ase, an escape, or a predato r encounter worth in vestigatin g.

select MAX(speed_kmph)  as top_speed_ever
 from GPSLogs;

-- 42. Count the animals collared in  each reserve, and shortlist only the reserves currently trackin g more than 15 animals — these may need add itional ranger support.

select reserve_id, COUNT(*)  as animal_count
 from Animals
group by reserve_id
HAVinG COUNT(*) > 15;

-- 43. Group all logs by reserve and identify which reserves have an average collar battery level below 20%— these need a battery-replacement drive scheduled immediately.
select r.reserve_id, r.reserve_name, AVG(g.battery_level_pct)  as avg_battery
 from Reserves r
inner join  Animals a
on r.reserve_id = a.reserve_id
inner join  GPSLogs g
on a.animal_id  = g.animal_id
group by r.reserve_id, r.reserve_name
HAVinG AVG(g.battery_level_pct) < 20;

-- 44. The annual conservation report needs a sin gle consolidated result: for every reserve, the number ofanimals it holds, their average age, the average battery health of their collars, and a clear flag for any
-- reserve whose average battery health h as dropped below an acceptable level.

select r.reserve_id, r.reserve_name,
COUNT(distinct  a.animal_id)  as animal_count,
AVG(a.estimated_age)  as avg_age,
AVG(g.battery_level_pct)     as avg_battery,
case when AVG(g.battery_level_pct) < 30
then 'LOW BATTERY — NEEDS ATTENTIon' else 'OK'
end  as battery_flag
 from Reserves r
LEFT JOin  Animals a
on r.reserve_id = a.reserve_id
LEFT JOin  GPSLogs g 
on a.animal_id  = g.animal_id
group by r.reserve_id, r.reserve_name;

-- 45. A recent firmware change alter ed how battery percentage gets reported by one collar model. Correct all currently sto red battery readin gs for the affected reserve so they reflect the new calibration.

update   GPSLogs
set  battery_level_pct = least(100, battery_level_pct + 10)
where animal_id in  (
select animal_id  from Animals where reserve_id = 3 );

-- 46. Produce a sin gle combin ed list of every reserve and every animal to gether — in cludin g reserves with zero animals and any
-- animal record that's somehow missin g its reserve — so not hin g gets left out of the audit.

select r.reserve_id, r.reserve_name, a.animal_id, a.tag_code
 from Reserves r
LEFT JOin  Animals a 
on r.reserve_id = a.reserve_id
UNIon
select r.reserve_id, r.reserve_name, a.animal_id, a.tag_code
 from Reserves r
RIGHT JOin  Animals a 
on r.reserve_id = a.reserve_id;

-- 47. Fin d every species that h as at le ast one tracked in dividual livin g in  a reserve that w as established before the year 2000.

select distincts.species_name
 from Species s
inner join  Animals a  
on s.species_id  = a.species_id
inner join  Reserves r 
on a.reserve_id  = r.reserve_id
where r.established_year < 2000;

-- 48. After a recent data cleanup, a few GPS logs may now poin t to  an animal ID that no longer exists in  the system. Track down these orphaned records.

select g.*
 from GPSLogs g
LEFT JOin  Animals a on g.animal_id = a.animal_id
where a.animal_id IS NULL;

-- 49. Calculate a combin ed activity score per animal usin g its log count and average speed  as an in termediate result, then use that to  rank  reserves by over all animal activity.
WITH animal_activity  as (
select a.reserve_id, g.animal_id,
COUNT(*)  as log_count,
AVG(g.speed_kmph)  as avg_speed,
COUNT(*) * AVG(g.speed_kmph)  as activity_score
 from Animals a
inner join  GPSLogs g on a.animal_id = g.animal_id
group by a.reserve_id, g.animal_id
)
select reserve_id, SUM(activity_score)  as total_reserve_activity
 from animal_activity
group by reserve_id
order by   total_reserve_activity desc ;

-- 50. A batch of very old GPS logs  from a decommissioned first-generation collar model is clutterin g the
-- datab ase and is no longer needed for any analysis. Remove exactly those records and not hin g else.

DELETE  from GPSLogs
where animal_id in  (
select animal_id  from Animals where collar_manufacturer = 'FirstGen Collars in c.'
);


-- 51. A junior data-entry volunteer tries to  save a new animal record without specifyin g which species it belongs to . What should prevent that in complete record  from bein g saved?

alter  table Animals MODIFY species_id int not  NULL;

-- 52. Build an in termediate reserve-by-reserve average battery level, then use it to  flag every reserve sittin g below the alliance-wide average.

WITH reserve_avg  as (
select a.reserve_id, AVG(g.battery_level_pct)  as reserve_avg_battery
 from Animals a
inner join  GPSLogs g 
on a.animal_id = g.animal_id
group by a.reserve_id
)
select reserve_id, reserve_avg_battery
 from reserve_avg
where reserve_avg_battery < (select AVG(reserve_avg_battery)  from reserve_avg);

-- 53. The reportin g d ashboard constantly filters by reserve and date range to gether, and the two filters are almost always used side by side. 
-- How would you set  the datab ase up so this specific combin ed search runs f aster?

 create index idx_animals_reserve on Animals(reserve_id);
 create index idx_gpslogs_animal_datetime on GPSLogs(animal_id, log_datetime);

-- 54. A bulk import left several reserve names with accidental leadin g or trailin g spaces. Clean these up before they go in to  the annual prin ted report.

update   Reserves
set  reserve_name = TRIM(reserve_name)
where reserve_id > 0;

-- 55. The rangers' mobile app needs a simplified, always-ready snapshot showin g each animal's tag code,species, reserve, and latest battery level, without the field team havin g to  reconstruct the full picture
--  from scratch every sin gle time.

 create view AnimalSnapshot  as
select a.animal_id, a.tag_code, s.species_name, r.reserve_name,
(select g.battery_level_pct
 from GPSLogs g
where g.animal_id = a.animal_id
order by   g.log_datetime desc 
limit 1)  as latest_battery_pct
 from Animals a
inner  JOin  Species s  
on a.species_id  = s.species_id
inner join  Reserves r 
on a.reserve_id  = r.reserve_id;

-- 56. The donor relations team keeps  askin g for the same list — every Critically Endangered animal with its reserve and species details. set  up somethin g they can pull directly, without you explain in g the
-- underlyin g tables every time they  ask.

 create view CriticallyEndangeredAnimals  as
select a.animal_id, a.tag_code, s.species_name, r.reserve_name
 from Animals a
inner join  Species s  
on a.species_id  = s.species_id
inner join  Reserves r 
on a.reserve_id  = r.reserve_id
where s.conservation_status = 'Critically Endangered';


-- 57. The data team wants to  understand over all data volume: how many GPS pin gs have been logged in  to tal sin ce the programme began?

select COUNT(*)  as total_pings_logged
 from GPSLogs;

-- 58. A field officer accidentally types an animal's estimated age  as a negative number. How do you make sure this kin d of entry is rejected the moment it's submitted?

alter  table Animals add  constraint chk_age_nonnegative CHECK (estimated_age >= 0);

-- 59. Split all tracked animals in to  three roughly equal age tiers, to  help the biology team design three different age-specific conservation strategies.

select a1.animal_id, a1.estimated_age,
case
when (select COUNT(*)  from Animals a2 where a2.estimated_age <= a1.estimated_age)
<= (select COUNT(*)  from Animals) / 3
then 1
when (select COUNT(*)  from Animals a2 where a2.estimated_age <= a1.estimated_age)
<= 2 * (select COUNT(*)  from Animals) / 3
then 2
else 3
end  aage_tier 
from Animals a1
order by   a1.estimated_age;

-- 60. Pull every GPS log belongin g specifically to  the one animal that recorded the lowest battery level ever logged in  the system.

WITH lowest_battery_animal  as (
select animal_id  from GPSLogs order by   battery_level_pct  asC limit 1
)
select g.*
 from GPSLogs g
where g.animal_id = (select animal_id  from lowest_battery_animal);

-- 61. A data-entry mistake caused an entire reserve's animals to  be logged under the wrong reservealto gether. Correct this in  one sweep rather than animal by animal.

update   Animals
set  reserve_id = 5   
where reserve_id = 2;

-- 62. For each animal, show what the very next recorded speed readin g will be, placed right alongside the current one, to  help spot a pattern buildin g up across consecutive readin gs.

select g1.animal_id, g1.log_datetime, g1.speed_kmph,
(select g2.speed_kmph
 from GPSLogs g2
where g2.animal_id = g1.animal_id
and g2.log_datetime > g1.log_datetime
order by   g2.log_datetime  asC
limit 1)  as next_speed
 from GPSLogs g1
order by   g1.animal_id, g1.log_datetime;

-- 63. Within  each reserve, order its animals by estimated age, oldest first, to  identify in dividuals that might need closer health monito rin g.

select reserve_id, animal_id, estimated_age,
rank () over  (PARTITIon BY reserve_id 
order by   estimated_age desc )  as age_rank 
 from Animals
order by   reserve_id, age_rank ;
-- 64. A new GPS pin g arrives tagged to  an animal ID that w as never registered in  the system. Explain  what should happen to  this record, and why it must not  be allowed to  slip through quietly.

alter  table GPSLogs
  add  ConSTRAinT fk_gpslogs_animal FOREIGN KEY (animal_id) REFERENCES Animals(animal_id);
  
-- 65. Cross-check reserves again st recent activity to  identify any reserve where absolutely no GPS pin gs
-- have come in  durin g the p ast seven days — this could mean a communication blackout or a bigger problem on the ground.

select r.reserve_id, r.reserve_name
 from Reserves r
where r.reserve_id not  in  (
select distinct  a.reserve_id
 from Animals a
inner join  GPSLogs g 
on a.animal_id = g.animal_id
where g.log_datetime >= DATE_SUB(CURDATE(), interval 7 DAY)
);

-- 66. Across the entire programme, order every GPS log by recorded speed to  surface the se ason's most extreme movement events, makin g sure that if two logs share the exact same to p speed, neither one
-- gets unfairly skipped in  the orderin g.

select log_id, animal_id, speed_kmph,
rank () over  (order by   speed_kmph desc )  as speed_rank 
 from GPSLogs
order by   speed_kmph desc ;

-- 67. Group the collarin g activity by the exact quarter of the year each animal w as fitted, to  compare how collarin g effort h as changed across different ph ases of the programme.

select species_id,
EXTRACT(YEAR  from collar_fitted_date)     as fit_year,
EXTRACT(QUARTER  from collar_fitted_date)  as fit_quarter,
COUNT(*)  as animals_fitted
 from Animals
group by species_id, fit_year, fit_quarter
order by   species_id, fit_year, fit_quarter;

-- 68. For each animal, lookin g at its logs in  date order, show what its battery level w as on the readin g immediately before the current one — this helps catch any sudden, unexplain ed battery drop.

select g1.animal_id, g1.log_datetime, g1.battery_level_pct,
(select g2.battery_level_pct
 from GPSLogs g2
where g2.animal_id = g1.animal_id
and g2.log_datetime < g1.log_datetime
order by   g2.log_datetime desc 
limit 1)  as previous_battery
 from GPSLogs g1
order by   g1.animal_id, g1.log_datetime;

-- 69. A new field researcher is join in g the team and should only be able to  look at animal and GPS data,never change any of it. set  up their access accordin gly.

DROP role IF EXISTS field_researcher;

 create role field_researcher;
grant select on projects.Animals to  field_researcher;
grant select on projects.GPSLogs to  field_researcher;

 create USER 'new_researcher_username'@'%' IDENTIFIED BY 'a_temporary_p assword';
grant field_researcher to  'new_researcher_username'@'%';
set  DEFAULT role field_researcher to  'new_researcher_username'@'%';



-- 70. List every animal along with its most recent recorded coordin ates, makin g sure animals whose collars haven't reported anythin g yet still appear on the list rather than disappearin g.
select animal_id, tag_code, latitude, longitude, log_datetime
 from (
select a.animal_id, a.tag_code, g.latitude, g.longitude, g.log_datetime,
ROW_NUMBER() over  (PARTITIon BY a.animal_id order by   g.log_datetime desc )  as rn
 from Animals a
LEFT JOin  GPSLogs g on a.animal_id = g.animal_id
) ranked
where rn = 1;

-- 71. The lead veterin arian needs the ability to  update   animal health-related details directly, unlike the rest of the field staff. set  up an access level that reflects this difference.
 create role IF not  EXISTS lead_veterinarian;
grant select, update   (estimated_age, sex) on projects.Animals to  lead_veterinarian;

 create USER IF not  EXISTS 'vet_username'@'%' IDENTIFIED BY 'a_temporary_p assword';
grant lead_veterinarian to  'vet_username'@'%';
set  DEFAULT role lead_veterinarian to  'vet_username'@'%';

-- 72. Identify every animal that belongs to  whichever sin gle species currently h as the highest number of tracked in dividuals.

select a.*
 from Animals a
where a.species_id = (
select species_id  from Animals group by species_id order by   COUNT(*) desc  limit 1
);

-- 73. After several months and a few team changes, nobody quite remembers what w as set  up to  speed up lookups on the GPS log table. Check what's currently in  place.
SHOW index  from GPSLogs;

-- 74. B ased on recorded speed, tag each GPS log  as 'Restin g', 'Movin g', or 'F ast Movement', to  help spot unusual chase or escape events buried in  the raw data.

select log_id, speed_kmph,
case
when speed_kmph < 2 then 'Restin g'
when speed_kmph between 2 and 15 then 'Movin g'
else 'Fast Movement'
end as movement_status
 from GPSLogs;
-- 75. For a nocturnal-behaviour study, pull all GPS logs that were recorded between 6 PM and 6 AM.

select *
 from GPSLogs
where EXTRACT(HOUR  from log_datetime) >= 18
OR EXTRACT(HOUR  from log_datetime) < 6;







